CREATE TABLE categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 80),slug TEXT NOT NULL UNIQUE,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE products(id INTEGER PRIMARY KEY,category_id INTEGER NOT NULL REFERENCES categories(id),sku TEXT NOT NULL UNIQUE CHECK(length(sku) BETWEEN 1 AND 64),slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 120),description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 4000),base_price_cents INTEGER NOT NULL CHECK(base_price_cents BETWEEN 1 AND 100000000),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),is_featured INTEGER NOT NULL DEFAULT 0 CHECK(is_featured IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE product_images(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),asset_path TEXT NOT NULL,alt_text TEXT NOT NULL CHECK(length(alt_text)>0),position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 3),UNIQUE(product_id,position));
CREATE TABLE inventory(product_id INTEGER PRIMARY KEY REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 0 AND 1000000),version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE promotions(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),category_id INTEGER REFERENCES categories(id),kind TEXT NOT NULL CHECK(kind IN('FINAL_PRICE','PERCENT_BPS')),value INTEGER NOT NULL CHECK(value>0),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,terms TEXT NOT NULL CHECK(length(terms) BETWEEN 1 AND 500),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1,CHECK((product_id IS NOT NULL)+(category_id IS NOT NULL)=1),CHECK((kind='FINAL_PRICE' AND product_id IS NOT NULL) OR (kind='PERCENT_BPS' AND category_id IS NOT NULL AND value<10000)),CHECK(starts_at<ends_at));
CREATE INDEX products_category ON products(category_id,is_active);
